234	    /**
235	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
236	     * The address is normalized in place (so a required-field check that follows rejects an
237	     * address blank after normalization), the required fields are checked, the telephone and
238	     * email are normalized in place, and the resulting owner is rejected when its derived
239	     * identity key already belongs to another owner. Each rule
240	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
241	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
242	     * to be mapped and saved.
243	     *
244	     * @param ownerFieldsDto the submitted owner fields, normalized in place
245	     */
246	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
247	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
248	        validateRequiredFields(ownerFieldsDto);
249	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
250	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
251	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
252	        rejectDuplicateIdentity(ownerFieldsDto);
253	        rejectCityAtCapacity(ownerFieldsDto.getCity());
254	        rejectDailyLimitExceeded(registrationDate);
255	    }
256	
257	    /**
258	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
259	     * falls on a business day. The date supplied on the request is used when present, otherwise the
260	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
261	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
262	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
263	     * membership number's year segment, the per-day create limit) is computed against.
264	     *
265	     * A supplied registration date later than the server's current date is rejected with an
266	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
267	     *
268	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
269	     * @return the effective registration date rolled forward to the next business day
270	     */
271	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
272	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
273	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
274	            throw new InvalidFieldsException(List.of("registrationDate"));
275	        }
276	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
277	        return toBusinessDay(effective);
278	    }
279	
280	    /**
281	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
282	     * following Monday, while a weekday is returned unchanged.
283	     *
284	     * @param date the date to adjust
285	     * @return the same date when it is a weekday, otherwise the next Monday
286	     */
287	    private LocalDate toBusinessDay(LocalDate date) {
288	        java.time.DayOfWeek day = date.getDayOfWeek();
289	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
290	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
291	        }
292	        return date;
293	    }
