295	    /**
296	     * The maximum number of owners that may be created on a single day. Once this many owners
297	     * already carry today's {@code registrationDate}, no further owner may be created today.
298	     */
299	    private static final long DAILY_OWNER_LIMIT = 100L;
300	
301	    /**
302	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
303	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
304	     * date the new owner would be stored with, so owners are capped per business day. When the limit
305	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
306	     * advice renders as a 429 Too Many Requests response.
307	     *
308	     * @param registrationDate the adjusted business-day registration date of the owner being created
309	     */
310	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
311	        long count = this.clinicService.findAllOwners().stream()
312	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
313	            .count();
314	        if (count >= DAILY_OWNER_LIMIT) {
315	            throw new DailyOwnerLimitExceededException(registrationDate);
316	        }
317	    }
318	
319	    /**
320	     * The number of owners that may carry a single day's {@code registrationDate} before that day
321	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
322	     * the create and read responses report {@code bulkSignupWarning} true for that date.
323	     */
324	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
325	
326	    /**
327	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
328	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
329	     * count is taken against the same adjusted date owners are stored with, mirroring the
330	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
331	     *
332	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
333	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
334	     */
335	    private boolean bulkSignupWarning(LocalDate registrationDate) {
336	        if (registrationDate == null) {
337	            return false;
338	        }
339	        long count = this.clinicService.findAllOwners().stream()
340	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
341	            .count();
342	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
343	    }
