345	    /**
346	     * The maximum number of owners a single city may hold. Once a city already contains this
347	     * many owners, no further owner may be created in it.
348	     */
349	    private static final long CITY_OWNER_CAPACITY = 50L;
350	
351	    /**
352	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
353	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
354	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
355	     * which the exception advice renders as a 409 Conflict response.
356	     *
357	     * @param city the city of the owner being created
358	     */
359	    private void rejectCityAtCapacity(String city) {
360	        long count = this.clinicService.findAllOwners().stream()
361	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
362	            .count();
363	        if (count >= CITY_OWNER_CAPACITY) {
364	            throw new CityCapacityExceededException(city);
365	        }
366	    }
