368	    /**
369	     * Builds the customer code assigned to a newly created owner. The code is formatted as
370	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
371	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
372	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
373	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
374	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
375	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
376	     * identity scheme needs.
377	     *
378	     * @param owner the owner being created, whose fields the code is derived from
379	     * @return the formatted customer code
380	     */
381	    private String customerCodeFor(Owner owner) {
382	        String region = owner.getRegion();
383	        String regionCode = region != null ? region : "UNKNOWN";
384	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
385	        return deduplicateCustomerCode(regionCode + "-" + hash8);
386	    }
387	
388	    /**
389	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
390	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
391	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
392	     *
393	     * @param baseCode the customer code computed for the owner being created
394	     * @return the base code when it is already unique, otherwise the de-duplicated code
395	     */
396	    private String deduplicateCustomerCode(String baseCode) {
397	        Set<String> existing = this.clinicService.findAllOwners().stream()
398	            .map(Owner::getCustomerCode)
399	            .filter(Objects::nonNull)
400	            .collect(Collectors.toSet());
401	        if (!existing.contains(baseCode)) {
402	            return baseCode;
403	        }
404	        int n = 2;
405	        while (existing.contains(baseCode + "-" + n)) {
406	            n++;
407	        }
408	        return baseCode + "-" + n;
409	    }
410	
411	    /**
412	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
413	     * with the owner being created, compared case-insensitively. The count is taken before the
414	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
415	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
416	     *
417	     * @param firstName the first name of the owner being created
418	     * @param lastName the last name of the owner being created
419	     * @return the number of pre-existing owners sharing the same first and last name
420	     */
421	    private int countNamesakes(String firstName, String lastName) {
422	        return (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
424	                && lastName.equalsIgnoreCase(existing.getLastName()))
425	            .count();
426	    }
