428	    /**
429	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
430	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
431	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
432	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
433	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
434	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
435	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
436	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
437	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
438	     * postcode and is never a possible duplicate.
439	     *
440	     * @param owner the owner being created, already carrying its normalized telephone and postcode
441	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
442	     */
443	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
444	        owner.setPossibleDuplicate(false);
445	        owner.setPossibleDuplicateOf(null);
446	        if (sharesHousehold(ownerFieldsDto)) {
447	            return;
448	        }
449	        findPossibleDuplicate(owner).ifPresent(existing -> {
450	            owner.setPossibleDuplicate(true);
451	            owner.setPossibleDuplicateOf(existing.getId());
452	        });
453	    }
454	
455	    /**
456	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
457	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
458	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
459	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
460	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
461	     * {@link java.util.Optional#empty()} is returned.
462	     *
463	     * @param owner the owner being created, already carrying its normalized telephone and postcode
464	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
465	     */
466	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
467	        if (owner.getPostcode() == null) {
468	            return java.util.Optional.empty();
469	        }
470	        return this.clinicService.findAllOwners().stream()
471	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
472	                && owner.getPostcode().equals(existing.getPostcode())
473	                && !owner.getTelephone().equals(existing.getTelephone()))
474	            .findFirst();
475	    }
