477	    /**
478	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
479	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
480	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
481	     * the names of every offending field, which the exception advice renders as a 400 response
482	     * with an {@code errors} array.
483	     *
484	     * @param ownerFieldsDto the submitted owner fields
485	     */
486	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
487	        List<String> missing = new ArrayList<>();
488	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
489	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
490	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
491	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
492	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
493	        if (!missing.isEmpty()) {
494	            throw new RequiredFieldsMissingException(missing);
495	        }
496	    }
497	
498	    private void addIfBlank(List<String> missing, String fieldName, String value) {
499	        if (value == null || value.isBlank()) {
500	            missing.add(fieldName);
501	        }
502	    }
503	
504	    /**
505	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
506	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
507	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
508	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
509	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
510	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
511	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
512	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
513	     *
514	     * @param telephone the submitted telephone value
515	     * @return the normalized E.164 telephone
516	     */
517	    private String normalizeTelephone(String telephone) {
518	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
519	        String e164;
520	        if (cleaned.startsWith("+")) {
521	            e164 = "+" + cleaned.substring(1);
522	        } else {
523	            String national = cleaned;
524	            if (national.startsWith("0")) {
525	                national = national.substring(1);
526	            }
527	            e164 = "+61" + national;
528	        }
529	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
530	            throw new InvalidFieldsException(List.of("telephone"));
531	        }
532	        validateNationalNumberLength(e164);
533	        return e164;
534	    }
535	
536	    /**
537	     * Validates the national-number length of an already syntactically valid E.164 telephone
538	     * against its country code. When the number carries a country code this application recognizes
539	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
540	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
541	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
542	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
543	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
544	     * that is not recognized carries no per-country length rule and is left to the general
545	     * 8-to-15-digit E.164 check.
546	     *
547	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
548	     */
549	    private void validateNationalNumberLength(String e164) {
550	        String countryCode = Owner.countryCodeOf(e164);
551	        if (countryCode == null) {
552	            return;
553	        }
554	        int nationalLength = e164.length() - 1 - countryCode.length();
555	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
556	            throw new InvalidFieldsException(List.of("telephone"));
557	        }
558	    }
559	
560	    /**
561	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
562	     * and a domain containing at least one dot, none of the parts holding whitespace or a
563	     * second {@code @}.
564	     */
565	    private static final java.util.regex.Pattern EMAIL_PATTERN =
566	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
567	
568	    /**
569	     * Disposable email domains an owner may not register with. An email whose domain (compared
570	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
571	     */
572	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
573	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
574	
575	    /**
576	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
577	     * accepted and returned unchanged. When present it must be a syntactically valid address
578	     * whose domain is not on the disposable-domain blocklist (see
579	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
580	     * present but syntactically invalid or on a disposable domain an
581	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
582	     * response naming the {@code email} field.
583	     *
584	     * @param email the submitted email value, or {@code null} when omitted
585	     * @return the lower-cased email, or {@code null} when none was supplied
586	     */
587	    private String normalizeEmail(String email) {
588	        if (email == null) {
589	            return null;
590	        }
591	        String trimmed = email.trim();
592	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
593	            throw new InvalidFieldsException(List.of("email"));
594	        }
595	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
596	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
597	            throw new InvalidFieldsException(List.of("email"));
598	        }
599	        return canonicalEmail(trimmed);
600	    }
601	
602	    /**
603	     * Reduces an email to the canonical form used both to store it and to compare it against
604	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
605	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
606	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
607	     * value read back off an existing owner without risk of rejecting it. This is the single
608	     * definition of email identity: two emails denote the same address exactly when they
609	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
610	     * an email already on an existing owner can be compared for equality after both pass through
611	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
612	     *
613	     * @param email the email to canonicalize, or {@code null} when none was supplied
614	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
615	     */
616	    private String canonicalEmail(String email) {
617	        if (email == null) {
618	            return null;
619	        }
620	        return email.trim().toLowerCase(java.util.Locale.ROOT);
621	    }
622	
623	    /**
624	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
625	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
626	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
627	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
628	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
629	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
630	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
631	     * 400 response naming the {@code postcode} field.
632	     *
633	     * @param postcode the submitted postcode, or {@code null} when omitted
634	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
635	     */
636	    private void validatePostcode(String postcode, String city) {
637	        if (postcode == null) {
638	            return;
639	        }
640	        if (!postcode.matches("^[0-9]{4}$")) {
641	            throw new InvalidFieldsException(List.of("postcode"));
642	        }
643	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
644	        if (range != null) {
645	            int value = Integer.parseInt(postcode);
646	            if (value < range[0] || value > range[1]) {
647	                throw new InvalidFieldsException(List.of("postcode"));
648	            }
649	        }
650	    }
651	
652	    /**
653	     * Rejects a new owner that would join a household already occupied by an existing owner. The
654	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
655	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
656	     * two owners sharing a last name and postcode belong to the same household. When any existing
657	     * owner already carries that household identifier the new owner is a household duplicate and a
658	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
659	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
660	     * that household and bypasses this block, so it is created rather than rejected. An owner without
661	     * a postcode belongs to no shared household and is never a household duplicate.
662	     *
663	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
664	     */
665	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
666	        if (sharesHousehold(ownerFieldsDto)) {
667	            return;
668	        }
669	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
670	        if (householdId == null) {
671	            return;
672	        }
673	        boolean taken = this.clinicService.findAllOwners().stream()
674	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
675	        if (taken) {
676	            throw new DuplicateIdentityException(householdId);
677	        }
678	    }
679	
680	    /**
681	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
682	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
683	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
684	     * resolves to the same stable value automatically, without any explicit linking. An owner without
685	     * a postcode belongs to no shared household and is left without a household identifier.
686	     *
687	     * @param owner the newly created owner, mutated in place with its household identifier
688	     */
689	    private void assignHousehold(Owner owner) {
690	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
691	    }
692	
693	    /**
694	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
695	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
696	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
697	     * every rule that treats a declared household member differently from an independent owner.
698	     *
699	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
700	     * @return {@code true} when the request opted into sharing a household
701	     */
702	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
703	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
704	    }
705	
706	    /**
707	     * Derives the stable {@code householdId} shared by every owner in the household identified by
708	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
709	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
710	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
711	     * postcode — regardless of creation order or address — resolve to the same identifier
712	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
713	     * returned.
714	     *
715	     * @param lastName the household's last name
716	     * @param postcode the household's postcode, or {@code null} when the owner has none
717	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
718	     */
719	    private String householdIdFor(String lastName, String postcode) {
720	        if (postcode == null) {
721	            return null;
722	        }
723	        return shaHex(householdKey(lastName, postcode), 12);
724	    }
725	
726	    /**
727	     * Builds the canonical household key that identifies the household a {@code lastName} and
728	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
729	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
730	     * owner fields make up a household and how they are normalized;
731	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
732	     * owners in the same household resolve to the same key and therefore the same identifier.
733	     *
734	     * @param lastName the household's last name
735	     * @param postcode the household's postcode
736	     * @return the normalized household key
737	     */
738	    private String householdKey(String lastName, String postcode) {
739	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
740	    }
741	
742	    /**
743	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
744	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
745	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
746	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
747	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
748	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
749	     * an {@link IllegalStateException} is thrown.
750	     *
751	     * @param input the string to hash
752	     * @param hexChars the number of leading upper-case hex characters to return
753	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
754	     */
755	    private String shaHex(String input, int hexChars) {
756	        try {
757	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
758	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
759	            StringBuilder sb = new StringBuilder();
760	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
761	                sb.append(String.format("%02X", digest[i]));
762	            }
763	            return sb.substring(0, hexChars);
764	        }
765	        catch (java.security.NoSuchAlgorithmException e) {
766	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
767	        }
768	    }
769	
770	    /**
771	     * Counts the owners that belong to the household identified by the given {@code householdId},
772	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
773	     * of owners, so after a create it reflects the household's size including the newly persisted
774	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
775	     * household and yields {@code 0}.
776	     *
777	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
778	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
779	     */
780	    private int countHouseholdMembers(String householdId) {
781	        if (householdId == null) {
782	            return 0;
783	        }
784	        return (int) this.clinicService.findAllOwners().stream()
785	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
786	            .count();
787	    }
788	
789	    /**
790	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
791	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
792	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
793	     *
794	     * @param value the value to collapse, or {@code null}
795	     * @return the whitespace-collapsed value, never {@code null}
796	     */
797	    private String collapseWhitespace(String value) {
798	        if (value == null) {
799	            return "";
800	        }
801	        return value.trim().replaceAll("\\s+", " ");
802	    }
803	
804	    /**
805	     * Common street-type abbreviations expanded during address normalization, keyed by their
806	     * upper-cased token.
807	     */
808	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
809	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
810	
811	    /**
812	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
813	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
814	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
815	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
816	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
817	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
818	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
819	     * everywhere an address is stored or compared.
820	     *
821	     * @param address the submitted address value, or {@code null}
822	     * @return the normalized address, never {@code null}
823	     */
824	    private String normalizeAddress(String address) {
825	        if (address == null) {
826	            return "";
827	        }
828	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
829	        if (collapsed.isEmpty()) {
830	            return "";
831	        }
832	        String[] tokens = collapsed.split(" ");
833	        StringBuilder sb = new StringBuilder(collapsed.length());
834	        for (int i = 0; i < tokens.length; i++) {
835	            if (i > 0) {
836	                sb.append(' ');
837	            }
838	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
839	        }
840	        return sb.toString();
841	    }
842	}
